//! Content identities for a sealed fixed point.
//!
//! The seal binds source, image, proof, facets, generated bytes, and the
//! generator closure. The closure names each generator's owner, contract,
//! qualified implementation, and the semantic bytes it reads.

use std::collections::BTreeMap;

use sim_artifact_facet::{ArtifactFacet, RegionOwnership, RegionSelector};
use sim_kernel::{ContentId, Datum, Symbol};

use super::{FactGenerator, FixedError};
use crate::{ProofOutcome, Revision};

pub(super) fn generator_seal(
    revision: &Revision,
    generators: &[&dyn FactGenerator],
) -> Result<Option<ContentId>, FixedError> {
    let mut ordered: Vec<&dyn FactGenerator> = generators.to_vec();
    ordered.sort_by(|left, right| {
        left.owner()
            .content_id()
            .cmp(right.owner().content_id())
            .then_with(|| left.writes().cmp(right.writes()))
    });
    let mut rows = Vec::new();
    for generator in ordered {
        let mut semantic = Vec::new();
        for path in generator.reads() {
            let Some(bytes) = revision.images().get(path) else {
                return Ok(None);
            };
            semantic.push(Datum::Node {
                tag: Symbol::qualified("roadmap-runner", "SemanticReadV1"),
                fields: vec![
                    (Symbol::new("path"), Datum::String(path.clone())),
                    (Symbol::new("bytes"), Datum::Bytes(bytes.clone())),
                ],
            });
        }
        let reads = generator
            .reads()
            .iter()
            .cloned()
            .map(Datum::String)
            .collect();
        let writes = generator
            .writes()
            .iter()
            .cloned()
            .map(Datum::String)
            .collect();
        rows.push(Datum::Node {
            tag: Symbol::qualified("roadmap-runner", "GeneratorBindingV1"),
            fields: vec![
                (
                    Symbol::new("owner"),
                    id_datum(generator.owner().content_id()),
                ),
                (
                    Symbol::new("implementation"),
                    id_datum(&generator.implementation()),
                ),
                (Symbol::new("reads"), Datum::List(reads)),
                (Symbol::new("writes"), Datum::List(writes)),
                (Symbol::new("semantic-reads"), Datum::List(semantic)),
            ],
        });
    }
    node("GeneratorClosureV1", Datum::List(rows)).map(Some)
}

pub(super) fn accepted_generated(
    revision: &Revision,
    facets: &[ArtifactFacet],
) -> Option<BTreeMap<String, Vec<u8>>> {
    let mut generated = BTreeMap::new();
    for facet in facets {
        let RegionSelector::ExactPath(path) = facet.region() else {
            return None;
        };
        let RegionOwnership::Generated { .. } = facet.ownership() else {
            continue;
        };
        generated.insert(path.clone(), revision.images().get(path)?.clone());
    }
    Some(generated)
}

pub(super) fn proof_digest(
    revision: &Revision,
    proofs: &BTreeMap<String, ProofOutcome>,
) -> Result<ContentId, FixedError> {
    let votes = revision
        .claims()
        .keys()
        .map(|id| {
            let outcome = match proofs.get(id) {
                Some(ProofOutcome::Passed) => "passed",
                Some(ProofOutcome::Failed) => "failed",
                None => "absent",
            };
            Datum::Node {
                tag: Symbol::qualified("roadmap-runner", "ProofVoteV1"),
                fields: vec![
                    (Symbol::new("claim"), Datum::String(id.clone())),
                    (Symbol::new("outcome"), Datum::String(outcome.to_owned())),
                ],
            }
        })
        .collect();
    node("ProofDigestV1", Datum::List(votes))
}

pub(super) fn facet_digest(facets: &[ArtifactFacet]) -> Result<ContentId, FixedError> {
    let mut ids: Vec<&ContentId> = facets.iter().map(|facet| facet.id().content_id()).collect();
    ids.sort();
    node(
        "FacetDigestV1",
        Datum::List(ids.into_iter().map(id_datum).collect()),
    )
}

pub(super) fn bind_seal(
    source: &ContentId,
    image: &ContentId,
    proof: &ContentId,
    facets: &ContentId,
    generated: &BTreeMap<String, Vec<u8>>,
    generators: &ContentId,
) -> Result<ContentId, FixedError> {
    let mut list = vec![
        id_datum(source),
        id_datum(image),
        id_datum(proof),
        id_datum(facets),
        id_datum(generators),
    ];
    for (path, bytes) in generated {
        list.push(fact_datum(path, bytes));
    }
    node("FixedPointV1", Datum::List(list))
}

pub(super) fn image(images: &BTreeMap<String, Vec<u8>>) -> Result<ContentId, FixedError> {
    crate::image_id(images).map_err(|error| FixedError::Identity(error.to_string()))
}

fn fact_datum(path: &str, bytes: &[u8]) -> Datum {
    Datum::Node {
        tag: Symbol::qualified("roadmap-runner", "GeneratedFactV1"),
        fields: vec![
            (Symbol::new("path"), Datum::String(path.to_owned())),
            (Symbol::new("bytes"), Datum::Bytes(bytes.to_vec())),
        ],
    }
}

fn id_datum(id: &ContentId) -> Datum {
    Datum::Node {
        tag: Symbol::qualified("core", "ContentId"),
        fields: vec![
            (
                Symbol::new("algorithm"),
                Datum::Symbol(id.algorithm.clone()),
            ),
            (Symbol::new("bytes"), Datum::Bytes(id.bytes.to_vec())),
        ],
    }
}

fn node(name: &str, payload: Datum) -> Result<ContentId, FixedError> {
    Datum::Node {
        tag: Symbol::qualified("roadmap-runner", name),
        fields: vec![(Symbol::new("payload"), payload)],
    }
    .content_id()
    .map_err(|error| FixedError::Identity(error.to_string()))
}
